class Node:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def insert(n, v):
    if n is None:
        return Node(v)
    if v < n.val:
        n.left = insert(n.left, v)
    else:
        n.right = insert(n.right, v)
    return n

root = None
for v in [3, 1, 4, 2, 5]:
    root = insert(root, v)

def inorder(n):
    return inorder(n.left) + [n.val] + inorder(n.right) if n else []

print(inorder(root))

